def get_axioms() -> list:
    return []


def get_vars() -> dict:
    self = TensorVar('self')
    kernel_size = IntArrayVar('kernel_size')
    stride = IntArrayVar('stride')
    padding = IntArrayVar('padding')
    ceil_mode = Bool('ceil_mode')
    count_include_pad = Bool('count_include_pad')
    divisor_override = OptVar('divisor_override', Int('divisor_override' + '.val'))
    out = TensorVar('out')
    return {'self': self, 'kernel_size': kernel_size, 'stride': stride, 'padding': padding, 'ceil_mode': ceil_mode, 'count_include_pad': count_include_pad, 'divisor_override': divisor_override, 'out': out}


def build_solver() -> Solver:
    s = Solver()
    s.add(*get_axioms())
    return s
